<article class="jg-job-card">@if(\App\Services\JobPresentation::logo($job))<img class="jg-job-logo" src="{{ \App\Services\JobPresentation::logo($job) }}" alt="{{ $job->company?->company_name }} logo">@else<div class="jg-company-monogram" role="img" aria-label="Generated company initials; not an official employer logo">{{ mb_substr($job->company?->company_name ?? 'J', 0, 1) }}</div>@endif<div class="jg-job-body"><h3><a href="{{ route('public.job', $job->id) }}">{{ $job->title }}</a></h3><p>{{ $job->company?->company_name ?? 'Hiring employer' }}</p><div class="jg-job-meta"><span>⌖ {{ $job->country?->name ?? 'See job details' }}</span><span>▣ {{ $job->job_category?->name ?? 'Job opportunity' }}</span>@if($job->minimum_salary || $job->maximum_salary)<span>◉ {{ \App\Services\JobPresentation::salarySummary($job) }}</span>@endif</div><p class="jg-job-summary">{{ \Illuminate\Support\Str::limit($job->publicDescription($job->job_context ?? $job->job_responsibilities ?? ''), 140) }}</p><div class="jg-job-bottom"><a href="{{ route('public.job', $job->id) }}">View details →</a>@if($job->created_at)<time datetime="{{ $job->created_at->toIso8601String() }}">{{ $job->created_at->diffForHumans() }}</time>@endif</div></div></article>
